-- Additive, initially disabled. Accounts and outbox remain the canonical inventory/transport.
CREATE TABLE warmup_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN('REAL','SIMULATION')),version integer NOT NULL DEFAULT 1 CHECK(version>0),config jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(id,workspace_id,environment));
CREATE TRIGGER immutable_warmup_profiles BEFORE UPDATE OR DELETE ON warmup_profiles FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE warmup_pools(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN('REAL','SIMULATION')),version integer NOT NULL DEFAULT 1,profile_id uuid NOT NULL,enabled boolean NOT NULL DEFAULT false,paused boolean NOT NULL DEFAULT false,breaker_open boolean NOT NULL DEFAULT false,breaker_reason text,allow_small_pool_concentration boolean NOT NULL DEFAULT false,authorization_id uuid REFERENCES operation_authorizations(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,environment),UNIQUE(id,workspace_id,environment),FOREIGN KEY(profile_id,workspace_id,environment) REFERENCES warmup_profiles(id,workspace_id,environment));
CREATE TABLE warmup_identities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN('REAL','SIMULATION')),account_id uuid NOT NULL REFERENCES records(id),address_fingerprint text NOT NULL,address_ciphertext text NOT NULL,profile_ciphertext text NOT NULL,ownership_evidence text NOT NULL,profile_verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,environment,address_fingerprint),UNIQUE(account_id),UNIQUE(id,workspace_id,environment));
CREATE TABLE warmup_states(account_id uuid PRIMARY KEY REFERENCES records(id),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN('REAL','SIMULATION')),pool_id uuid NOT NULL,identity_id uuid,profile_id uuid NOT NULL,status text NOT NULL DEFAULT 'AWAITING_CONNECTION' CHECK(status IN('AWAITING_CONNECTION','AWAITING_IDENTITY','AWAITING_PROFILE','PROFILE_WAIT','AWAITING_PEER','AWAITING_CONTENT','WARMING','PAUSED','GRADUATED','QUARANTINED')),reason text NOT NULL DEFAULT 'POOL_MEMBER',effective_days integer NOT NULL DEFAULT 0 CHECK(effective_days>=0),extensions integer NOT NULL DEFAULT 0 CHECK(extensions BETWEEN 0 AND 2),profile_ready_at timestamptz,stable_since timestamptz,last_observed_at timestamptz,last_completed_date date,confirmed_block boolean NOT NULL DEFAULT false,enrolled_at timestamptz,warmup_started_at timestamptz,graduated_at timestamptz,paused boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,workspace_id,environment),FOREIGN KEY(pool_id,workspace_id,environment) REFERENCES warmup_pools(id,workspace_id,environment),FOREIGN KEY(profile_id,workspace_id,environment) REFERENCES warmup_profiles(id,workspace_id,environment),FOREIGN KEY(identity_id,workspace_id,environment) REFERENCES warmup_identities(id,workspace_id,environment));
CREATE TABLE warmup_content(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL CHECK(environment IN('REAL','SIMULATION')),content_hash text NOT NULL,body jsonb NOT NULL,approved_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,environment,content_hash),UNIQUE(id,workspace_id,environment));
CREATE TRIGGER immutable_warmup_content BEFORE UPDATE OR DELETE ON warmup_content FOR EACH ROW EXECUTE FUNCTION immutable_row();
CREATE TABLE warmup_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL,account_id uuid NOT NULL,profile_id uuid NOT NULL,local_date date NOT NULL,effective_day integer NOT NULL,budget jsonb NOT NULL,planned_messages integer NOT NULL DEFAULT 0,planned_conversations integer NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'PLANNED',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,local_date),UNIQUE(id,workspace_id,environment),FOREIGN KEY(account_id,workspace_id,environment) REFERENCES warmup_states(account_id,workspace_id,environment),FOREIGN KEY(profile_id,workspace_id,environment) REFERENCES warmup_profiles(id,workspace_id,environment));
CREATE TABLE warmup_conversations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL,initiator_id uuid NOT NULL,peer_id uuid NOT NULL,content_id uuid NOT NULL,local_date date NOT NULL,status text NOT NULL DEFAULT 'PLANNED',created_at timestamptz NOT NULL DEFAULT now(),CHECK(initiator_id<>peer_id),UNIQUE(id,workspace_id,environment),FOREIGN KEY(initiator_id,workspace_id,environment) REFERENCES warmup_states(account_id,workspace_id,environment),FOREIGN KEY(peer_id,workspace_id,environment) REFERENCES warmup_states(account_id,workspace_id,environment),FOREIGN KEY(content_id,workspace_id,environment) REFERENCES warmup_content(id,workspace_id,environment));
CREATE TABLE warmup_turns(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL,conversation_id uuid NOT NULL,sender_id uuid NOT NULL,recipient_id uuid NOT NULL,position integer NOT NULL,content jsonb NOT NULL,status text NOT NULL DEFAULT 'PLANNED',not_before timestamptz NOT NULL,expires_at timestamptz NOT NULL,effect_id uuid UNIQUE REFERENCES outbox(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(sender_id<>recipient_id),UNIQUE(conversation_id,position),FOREIGN KEY(conversation_id,workspace_id,environment) REFERENCES warmup_conversations(id,workspace_id,environment),FOREIGN KEY(sender_id,workspace_id,environment) REFERENCES warmup_states(account_id,workspace_id,environment),FOREIGN KEY(recipient_id,workspace_id,environment) REFERENCES warmup_states(account_id,workspace_id,environment));
CREATE TABLE warmup_content_usage(workspace_id text NOT NULL,environment text NOT NULL,account_id uuid NOT NULL,content_hash text NOT NULL,conversation_id uuid NOT NULL REFERENCES warmup_conversations(id),PRIMARY KEY(workspace_id,environment,account_id,content_hash),FOREIGN KEY(account_id,workspace_id,environment) REFERENCES warmup_states(account_id,workspace_id,environment));
CREATE TABLE warmup_rate_buckets(account_id uuid NOT NULL REFERENCES records(id),window_start timestamptz NOT NULL,used integer NOT NULL DEFAULT 0 CHECK(used>=0),PRIMARY KEY(account_id,window_start));
CREATE TABLE warmup_rate_reservations(effect_id uuid NOT NULL REFERENCES outbox(id),account_id uuid NOT NULL REFERENCES records(id),window_start timestamptz NOT NULL,PRIMARY KEY(effect_id,account_id));
CREATE TABLE warmup_schedule_runs(pool_id uuid NOT NULL REFERENCES warmup_pools(id),kind text NOT NULL CHECK(kind IN('daily','health','reconcile')),window_key text NOT NULL,status text NOT NULL DEFAULT 'RUNNING',lease_until timestamptz NOT NULL DEFAULT now()+interval '5 minutes',result jsonb NOT NULL DEFAULT '{}',started_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,PRIMARY KEY(pool_id,kind,window_key));
CREATE TABLE warmup_observations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id text NOT NULL,environment text NOT NULL,account_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('HEALTHY','FAILED','CONFIRMED_BLOCK','INTERNAL_MESSAGE')),evidence_ref text NOT NULL,observed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(account_id,kind,evidence_ref),FOREIGN KEY(account_id,workspace_id,environment) REFERENCES warmup_states(account_id,workspace_id,environment));
CREATE VIEW warmup_pair_stats AS SELECT workspace_id,environment,least(initiator_id::text,peer_id::text) account_a,greatest(initiator_id::text,peer_id::text) account_b,local_date,count(*)::integer conversations FROM warmup_conversations GROUP BY 1,2,3,4,5;

CREATE FUNCTION guard_warmup_account() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM records WHERE id=NEW.account_id AND workspace_id=NEW.workspace_id AND environment=NEW.environment AND kind='channel_account' AND NOT(body?'deleted_at')) THEN RAISE EXCEPTION 'WARMUP_ACCOUNT_SCOPE_INVALID'; END IF;
 IF TG_OP='UPDATE' AND (NEW.account_id<>OLD.account_id OR NEW.workspace_id<>OLD.workspace_id OR NEW.environment<>OLD.environment) THEN RAISE EXCEPTION 'WARMUP_SCOPE_IMMUTABLE'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER guard_warmup_identity BEFORE INSERT OR UPDATE ON warmup_identities FOR EACH ROW EXECUTE FUNCTION guard_warmup_account();
CREATE TRIGGER guard_warmup_state BEFORE INSERT OR UPDATE ON warmup_states FOR EACH ROW EXECUTE FUNCTION guard_warmup_account();
CREATE FUNCTION guard_warmup_effect() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF TG_OP='UPDATE' AND NEW.kind IS DISTINCT FROM OLD.kind THEN RAISE EXCEPTION 'EFFECT_KIND_IMMUTABLE'; END IF;
 IF NEW.kind='warmup' AND NOT EXISTS(SELECT 1 FROM warmup_turns t JOIN warmup_conversations c ON c.id=t.conversation_id JOIN warmup_states a ON a.account_id=t.sender_id JOIN warmup_states b ON b.account_id=t.recipient_id WHERE t.id::text=NEW.payload->>'warmup_turn_id' AND t.workspace_id=NEW.workspace_id AND t.environment=NEW.environment AND t.sender_id::text=NEW.account_id AND t.recipient_id::text=NEW.contact_id AND t.conversation_id::text=NEW.conversation_id AND a.pool_id=b.pool_id AND ((t.sender_id=c.initiator_id AND t.recipient_id=c.peer_id) OR (t.sender_id=c.peer_id AND t.recipient_id=c.initiator_id))) THEN RAISE EXCEPTION 'WARMUP_EFFECT_SCOPE_INVALID'; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER guard_warmup_effect BEFORE INSERT OR UPDATE ON outbox FOR EACH ROW EXECUTE FUNCTION guard_warmup_effect();
GRANT SELECT ON warmup_profiles,warmup_pools,warmup_identities,warmup_states,warmup_content,warmup_plans,warmup_conversations,warmup_turns,warmup_content_usage,warmup_rate_buckets,warmup_rate_reservations,warmup_schedule_runs,warmup_observations,warmup_pair_stats TO commerce_api,commerce_automation,commerce_channel,commerce_maintenance;
GRANT INSERT ON warmup_profiles,warmup_content TO commerce_api;
GRANT INSERT,UPDATE ON warmup_pools,warmup_identities,warmup_states TO commerce_api;
GRANT UPDATE ON warmup_pools,warmup_states TO commerce_automation;
GRANT INSERT,UPDATE ON warmup_plans,warmup_conversations,warmup_turns,warmup_schedule_runs TO commerce_automation;
GRANT INSERT ON warmup_content_usage,warmup_observations TO commerce_automation;
GRANT UPDATE(profile_verified_at) ON warmup_identities TO commerce_channel;
GRANT INSERT,UPDATE ON warmup_rate_buckets TO commerce_channel;
GRANT INSERT ON warmup_rate_reservations,warmup_observations TO commerce_channel;
GRANT UPDATE ON warmup_states TO commerce_channel;
